import {drawDemo} from './demo.mjs';
import {opticalDensity,massDensity} from './science.mjs';
const $=id=>document.getElementById(id),all=s=>[...document.querySelectorAll(s)];
let user=null,authMode='login',view='home',heroFrame=null;
export const currentUser=()=>user;
const number=(n,d=4)=>Number(n).toLocaleString('tr-TR',{maximumSignificantDigits:d});
function text(tag,value,cls){const n=document.createElement(tag);n.textContent=value;if(cls)n.className=cls;return n;}
async function api(path,method='GET',body){let response;try{response=await fetch(path,{method,headers:method==='GET'?{}:{'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{}),signal:AbortSignal.timeout(15000)});}catch{throw new Error('Sunucuya ulaşılamadı. Bağlantıyı kontrol edip tekrar deneyin.');}const result=await response.json();if(!response.ok)throw new Error(result.error||'İşlem tamamlanamadı.');return result;}
function message(id,value,error=false){$(id).textContent=value;$(id).classList.toggle('error',error);}
function hero(){if(view!=='home'||document.hidden)return;drawDemo($('heroCanvas'),'stable',matchMedia('(prefers-reduced-motion: reduce)').matches?0:performance.now());if(!matchMedia('(prefers-reduced-motion: reduce)').matches)heroFrame=requestAnimationFrame(hero);}
function showView(next){if(next==="measure"){all(".method-view").forEach(e=>e.hidden=e.id!=="method-camera");all("[data-method]").forEach(e=>e.classList.toggle("active",e.dataset.method==="camera"));}view=next;all('.view').forEach(e=>e.hidden=e.id!=='view-'+next);all('#siteNav [data-nav]').forEach(e=>{const active=e.dataset.nav===next;e.classList.toggle('active',active);if(active)e.setAttribute('aria-current','page');else e.removeAttribute('aria-current');});$('siteNav').classList.remove('open');$('navToggle').setAttribute('aria-expanded','false');$('accountMenu').hidden=true;$('accountToggle').setAttribute('aria-expanded','false');if(heroFrame!==null)cancelAnimationFrame(heroFrame);window.dispatchEvent(new CustomEvent('viewchange',{detail:next}));if(next==='home')hero();if(next==='profile')renderUser();window.scrollTo({top:0,behavior:'instant'});}
all('[data-nav]').forEach(e=>e.onclick=event=>{event.preventDefault();showView(e.dataset.nav);});
$('navToggle').onclick=()=>{const open=$('siteNav').classList.toggle('open');$('navToggle').setAttribute('aria-expanded',String(open));};
$('accountToggle').onclick=()=>{if(!user){openAuth('login');return;}$('accountMenu').hidden=!$('accountMenu').hidden;$('accountToggle').setAttribute('aria-expanded',String(!$('accountMenu').hidden));};
document.addEventListener('click',e=>{if(!e.target.closest('.account-area')){$('accountMenu').hidden=true;$('accountToggle').setAttribute('aria-expanded','false');}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('accountMenu').hidden=true;$('accountToggle').setAttribute('aria-expanded','false');$('siteNav').classList.remove('open');$('navToggle').setAttribute('aria-expanded','false');}});
function renderUser(){
 $('accountName').textContent=user?'@'+user.username:'Giriş yap ↗';$('accountAvatar').hidden=!user;$('accountHandle').textContent=user?'@'+user.username:'';$('accountEmail').textContent=user?.email||'';$('profileGuest').hidden=!!user;$('profileContent').hidden=!user;$('memberWelcome').hidden=!user;$('memberGreeting').textContent=user?'Tekrar merhaba, '+user.name+'.':'';
 if(!user)return;
 for(const id of ['accountAvatar','profileLargeAvatar']){$(id).textContent=user.name.slice(0,1).toLocaleUpperCase('tr-TR');$(id).dataset.accent=user.accent;}
 $('profileHeadingName').textContent=user.name;$('profileHandle').textContent='@'+user.username;$('profileUsername').value=user.username;$('profileEmail').textContent=user.email;$('profileName').value=user.name;$('profileOrganization').value=user.organization;$('profileBio').value=user.bio;$('profileScenario').value=user.scenario;$('profileAccent').value=user.accent;$('accountSince').textContent='Üyelik tarihi: '+new Date(user.createdAt).toLocaleDateString('tr-TR');
}
function setUser(next){user=next;renderUser();window.dispatchEvent(new Event('accountchange'));}
function switchAuth(mode){authMode=mode;const register=mode==='register';$('authTitle').textContent=register?'Aramıza katıl.':'Yeniden merhaba.';$('authSubtitle').textContent=register?'Kullanıcı adını seç, kendi profilini oluştur.':'Kullanıcı adın veya e-postanla giriş yap.';$('authNameLabel').hidden=!register;$('authName').required=register;$('authUsernameLabel').hidden=!register;$('authUsername').required=register;$('authEmail').type=register?'email':'text';$('authIdentifierLabel').textContent=register?'E-posta':'Kullanıcı adı veya e-posta';$('authEmail').autocomplete=register?'email':'username';$('passwordHint').hidden=!register;$('authPassword').minLength=register?10:1;$('authPassword').autocomplete=register?'new-password':'current-password';$('authSubmit').textContent=register?'Kullanıcı hesabı oluştur ↗':'Giriş yap ↗';$('loginTab').classList.toggle('active',!register);$('registerTab').classList.toggle('active',register);message('authMessage','');}
function openAuth(mode){switchAuth(mode);$('authForm').reset();$('authPassword').type='password';$('togglePassword').textContent='Göster';$('togglePassword').setAttribute('aria-pressed','false');if(!$('authDialog').open)$('authDialog').showModal();}
all('[data-auth]').forEach(e=>e.onclick=()=>openAuth(e.dataset.auth));$('loginTab').onclick=()=>switchAuth('login');$('registerTab').onclick=()=>switchAuth('register');$('authClose').onclick=()=>$('authDialog').close();$('continueGuest').onclick=()=>$('authDialog').close();
$('togglePassword').onclick=()=>{const show=$('authPassword').type==='password';$('authPassword').type=show?'text':'password';$('togglePassword').textContent=show?'Gizle':'Göster';$('togglePassword').setAttribute('aria-pressed',String(show));$('togglePassword').setAttribute('aria-label',show?'Parolayı gizle':'Parolayı göster');};
$('authForm').onsubmit=async e=>{e.preventDefault();$('authSubmit').disabled=true;message('authMessage','İşlem yapılıyor…');try{const result=await api('/api/auth/'+authMode,'POST',{name:$('authName').value,username:$('authUsername').value,email:$('authEmail').value,identifier:$('authEmail').value,password:$('authPassword').value});setUser(result.user);$('authForm').reset();$('authDialog').close();showView('profile');}catch(error){message('authMessage',error.message,true);}finally{$('authSubmit').disabled=false;}};
async function logout(){try{await api('/api/auth/logout','POST',{});setUser(null);showView('home');}catch(error){message('profileMessage',error.message,true);$('accountMenu').hidden=true;showView('profile');}}
$('menuLogout').onclick=logout;$('profileLogout').onclick=logout;
$('profileForm').onsubmit=async e=>{e.preventDefault();const button=$('profileForm').querySelector('button');button.disabled=true;try{const result=await api('/api/me','PATCH',{name:$('profileName').value,username:$('profileUsername').value,organization:$('profileOrganization').value,bio:$('profileBio').value,scenario:$('profileScenario').value,accent:$('profileAccent').value});setUser(result.user);message('profileMessage','Profilin güncellendi.');}catch(error){message('profileMessage',error.message,true);}finally{button.disabled=false;}};
$('logoutOthers').onclick=async()=>{const button=$('logoutOthers');button.disabled=true;try{const result=await api('/api/auth/logout-others','POST',{});message('sessionMessage',result.count?result.count+' diğer oturum kapatıldı.':'Başka açık oturum bulunmuyor.');}catch(error){message('sessionMessage',error.message,true);}finally{button.disabled=false;}};
$('passwordForm').onsubmit=async e=>{e.preventDefault();const button=$('passwordForm').querySelector('button');button.disabled=true;try{await api('/api/auth/password','POST',{currentPassword:$('currentPassword').value,newPassword:$('newPassword').value});$('passwordForm').reset();message('passwordMessage','Parolan değiştirildi. Diğer oturumlar kapatıldı.');}catch(error){message('passwordMessage',error.message,true);}finally{button.disabled=false;}};
function method(name){all('.method-view').forEach(e=>e.hidden=e.id!=='method-'+name);all('[data-method]').forEach(e=>e.classList.toggle('active',e.dataset.method===name));window.dispatchEvent(new CustomEvent('viewchange',{detail:name==='camera'?'measure':'science'}));}
all('[data-method]').forEach(e=>e.onclick=()=>method(e.dataset.method));all('[data-science]').forEach(e=>e.onclick=()=>{showView('measure');method(e.dataset.science);});
function result(id,heading,lines,warning){const out=$(id);out.replaceChildren();out.className='science-output';out.append(text('strong',heading));for(const line of lines)out.append(text('p',line));if(warning)out.append(text('p',warning,'form-message error'));out.append(text('p','Saflık durumu: Bu ölçümle belirlenemez.','purity'));out.hidden=false;}
const value=id=>$(id).value.trim()===''?NaN:Number($(id).value);
$('opticalForm').onsubmit=e=>{e.preventDefault();$('opticalResult').hidden=true;try{if(!$('opticalConfirmed').checked)throw new Error('Deney koşullarını doğrulayın.');const r=opticalDensity(value('incident'),value('transmitted'),value('dark'));result('opticalResult','A = '+number(r.absorbance,5),['Düzeltilmiş ışık oranı T = '+number(r.transmittance,5),'Geçirgenlik: '+number(r.transmittance*100,5)+' %','Optik yoğunluk boyutsuzdur; g/mL cinsinden kütle yoğunluğu değildir.'],r.warning);message('opticalMessage','Hesaplama tamamlandı.');}catch(error){message('opticalMessage',error.message,true);}};
$('densityForm').onsubmit=e=>{e.preventDefault();$('densityResult').hidden=true;try{const r=massDensity(value('emptyMass'),value('fullMass'),value('volume'),value('temperature'));result('densityResult',number(r.gramsPerMl,5)+' g/mL',['SI birimiyle: '+number(r.kgPerM3,5)+' kg/m³','Net sıvı kütlesi: '+number(r.mass,5)+' g · Hacim: '+number(r.volume,5)+' mL','Ölçüm sıcaklığı: '+number(r.temperature,4)+' °C']);message('densityMessage','Yoğunluk, girdiğin fiziksel ölçümlerden hesaplandı.');}catch(error){message('densityMessage',error.message,true);}};
for(const [form,out,messageId]of [['opticalForm','opticalResult','opticalMessage'],['densityForm','densityResult','densityMessage']])$(form).addEventListener('input',()=>{$(out).hidden=true;message(messageId,'');});
document.addEventListener('visibilitychange',()=>{if(heroFrame!==null)cancelAnimationFrame(heroFrame);if(!document.hidden&&view==='home')hero();});
api('/api/me').then(result=>setUser(result.user)).catch(()=>message('authMessage','Oturum bilgisi alınamadı. Giriş yaparak tekrar deneyebilirsin.',true));
hero();
